def _get_warning_metadata(frame, skip_file_prefixes):
    """Get the warning metadata for a frame."""
    frame = _next_external_frame(frame, skip_file_prefixes)
    if frame is None:
        return None, None, None
    return frame.f_code.co_filename, frame.f_lineno, frame.f_locals


def _get_source(location):
    """Get the source code for a warning location."""
    import linecache
    filename, lineno = location
    if lineno is None:
        return None
    try:
        source = linecache.getline(filename, lineno)
    except Exception:
        # When a warning is logged during Python shutdown, linecache
        # and the import machinery don't work anymore
        return None
    return source.strip() if source else None


